=== SkeletonTile ===
/**
 * A reserved rectangle standing where a claim is about to arrive.
 *
 * **Not a shimmer, not a pulse, not a grey bar sliding across a card.** A space
 * held open, at the size and in the place the thing being waited for will take.
 * An animated placeholder is a tool performing busyness at a reader who is
 * waiting on a model call that takes half a minute; a held rectangle is a tool
 * saying where the next thing goes.
 *
 * **It is never a claim.** It has no identifier on the map — its name is a box's
 * name — it never reaches the network, it carries no likelihood, and there is no
 * number on it to be a number nobody computed, because there is no number on it
 * at all. The only thing it prints is one line the stream carried: the reader's
 * own sentence, or the words of the open claim it hangs off.
 *
 * Its box is a tile's box: 280 pixels wide and 152 tall, which is the floor of a
 * tile's own clamped height — so when the claim lands, it lands at least as tall
 * as the rectangle that was held for it and nothing above it moves.
 */

import { TILE_MIN_HEIGHT, TILE_WIDTH } from "../graph/geometry";
import "./skeletonTile.css";

/** What a reserved rectangle needs to draw itself. */
export interface SkeletonTileProps {
  /**
   * The one line it carries — the reader's own sentence, or *one step on from
   * "…"*, quoting the open claim this rectangle hangs off.
   *
   * Every character of it came off the stream or out of the reader's own typing.
   * Nothing here composes a sentence.
   */
  readonly words: string;
}

/** One reserved rectangle. */
export function SkeletonTile({ words }: SkeletonTileProps) {
  return (
    <div
      className="skeleton-tile"
      style={{ width: `${TILE_WIDTH}px`, height: `${TILE_MIN_HEIGHT}px` }}
    >
      {/* What the box is, in real words rather than in a label written for a
          reader who cannot see it — so the two readings are the same reading,
          and neither can drift from the other. */}
      <span className="skeleton-tile__mark">held open</span>
      <p className="skeleton-tile__words">{words}</p>
    </div>
  );
}

content.content:
/*
 * A reserved rectangle at the growing edge of the map.
 *
 * Everything here is deliberately quieter than a tile. It sits on `--surface`
 * rather than on `--surface-raised`, so it reads as a space held open rather than
 * as a card with nothing in it, and its border is one hairline with a dashed
 * pattern — dashed because "this is not here yet" has to survive a greyscale
 * print, and a fainter solid line would not.
 *
 * **No animation of any kind.** Nothing scales, pulses, sweeps or loops. The one
 * movement a rectangle is allowed is appearing and going, which is opacity and at
 * most `--duration-fast`.
 */

.skeleton-tile {
  display: grid;
  align-content: start;
  row-gap: var(--space-1);
  box-sizing: border-box;
  padding: var(--space-2);
  background: var(--surface);
  border: 1px dashed var(--hairline);
  border-radius: var(--radius);
  animation: skeleton-arrives var(--duration-fast) ease-out;
}

@keyframes skeleton-arrives {
  from {
    opacity: 0;
  }
}

/* What the box is, said in words rather than implied by a shape. Set in the
 * number face because it is a label on the interface rather than something
 * anybody claimed. */
.skeleton-tile__mark {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* The one line it carries, clamped to four so that a long sentence cannot grow
 * the box past the height the layout reserved for it. */
.skeleton-tile__words {
  margin: 0;
  font-family: var(--font-interface);
  font-size: var(--text-sm);
  line-height: 1.35;
  color: var(--text-muted);
  text-wrap: pretty;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  line-clamp: 4;
  overflow: hidden;
}
===== TileOverflow =====
/**
 * The tile that stands in for the tiles a column has no room for.
 *
 * A column of the map shows seven claims. When a map fans out wider than that,
 * the eighth and everything after it collapse into this one tile, which says
 * how many there are. The cap is what keeps a wide map readable instead of a
 * wall; saying the number out loud is what keeps it honest, because a map that
 * quietly dropped claims would be lying about its own shape.
 *
 * It is drawn the same width as a claim's tile and with the same one-pixel
 * outline, so the column keeps its rhythm — but at the shortest a tile is
 * allowed to be, and with a dashed line rather than a solid one, because it is
 * not a claim.
 */

import { TILE_MIN_HEIGHT, TILE_WIDTH } from "../graph/geometry";
import "./tile.css";

/** What the collapsed tile needs to draw itself. */
export interface TileOverflowProps {
  /** How many claims in this column are not drawn. */
  readonly count: number;
}

/** The "+n more" tile at the foot of a column that ran out of room. */
export function TileOverflow({ count }: TileOverflowProps) {
  const claims = count === 1 ? "claim" : "claims";
  return (
    <article
      className="tile tile--overflow"
      style={{ width: `${TILE_WIDTH}px`, height: `${TILE_MIN_HEIGHT}px` }}
      aria-label={`${count} more ${claims} in this column, not drawn`}
    >
      <svg
        className="tile__outline"
        width={TILE_WIDTH}
        height={TILE_MIN_HEIGHT}
        viewBox={`0 0 ${TILE_WIDTH} ${TILE_MIN_HEIGHT}`}
        aria-hidden="true"
        focusable="false"
      >
        <rect
          x="0.5"
          y="0.5"
          width={TILE_WIDTH - 1}
          height={TILE_MIN_HEIGHT - 1}
          rx="6"
          strokeDasharray="4 4"
        />
      </svg>
      <p className="tile__overflow-count" aria-hidden="true">
        {`+${count} more`}
      </p>
      <p className="tile__overflow-line">
        {`${claims} in this column that there is no room to draw side by side. They are on the map.`}
      </p>
    </article>
  );
}

